{"content": "1|import { useCallback, useEffect, useRef } from "react";
2|import { motion } from "motion/react";
3|
4|/**
5| * Dot-grid canvas background that glows where the cursor passes.
6| * Placed as a fixed full-screen layer behind everything.
7| */
8|export default function DotGridBackground() {
9|  const canvasRef = useRef(null);
10|  const mouse = useRef({ x: -9999, y: -9999 });
11|
12|  const handleMouseMove = useCallback((e) => {
13|    mouse.current = { x: e.clientX, y: e.clientY };
14|  }, []);
15|
16|  useEffect(() => {
17|    window.addEventListener("mousemove", handleMouseMove);
18|    return () => window.removeEventListener("mousemove", handleMouseMove);
19|  }, [handleMouseMove]);
20|
21|  useEffect(() => {
22|    const canvas = canvasRef.current;
23|    if (!canvas) return;
24|    const ctx = canvas.getContext("2d");
25|    if (!ctx) return;
26|
27|    const DOT_GAP = 28;
28|    const DOT_R = 1;
29|    const GLOW_RADIUS = 120;
30|
31|    let animId;
32|
33|    const resize = () => {
34|      canvas.width = window.innerWidth;
35|      canvas.height = window.innerHeight;
36|    };
37|    resize();
38|    window.addEventListener("resize", resize);
39|
40|    const draw = () => {
41|      const { width, height } = canvas;
42|      ctx.clearRect(0, 0, width, height);
43|
44|      const cols = Math.ceil(width / DOT_GAP) + 1;
45|      const rows = Math.ceil(height / DOT_GAP) + 1;
46|      const mx = mouse.current.x;
47|      const my = mouse.current.y;
48|
49|      for (let r = 0; r < rows; r++) {
50|        for (let c = 0; c < cols; c++) {
51|          const x = c * DOT_GAP;
52|          const y = r * DOT_GAP;
53|          const dist = Math.sqrt((x - mx) ** 2 + (y - my) ** 2);
54|          const proximity = Math.max(0, 1 - dist / GLOW_RADIUS);
55|          const base = 0.08;
56|          const bright = base + proximity * 0.65;
57|
58|          ctx.beginPath();
59|          ctx.arc(x, y, DOT_R + proximity * 1.2, 0, Math.PI * 2);
60|          // White dots with crimson highlight near cursor
61|          const r_val = Math.round(255 * (0.6 + proximity * 0.4));
62|          const g_val = Math.round(255 * (0.15 * proximity));
63|          const b_val = Math.round(255 * (0.1 * proximity));
64|          ctx.fillStyle = `rgba(${r_val},${g_val},${b_val},${bright})`;
65|          ctx.fill();
66|        }
67|      }
68|      animId = requestAnimationFrame(draw);
69|    };
70|
71|    draw();
72|    return () => {
73|      cancelAnimationFrame(animId);
74|      window.removeEventListener("resize", resize);
75|    };
76|  }, []);
77|
78|  return (
79|    <canvas
80|      ref={canvasRef}
81|      className="fixed inset-0 pointer-events-none z-0"
82|      style={{ mixBlendMode: "screen" }}
83|    />
84|  );
